 Json plan={{"type","dash"},{"live",true},{"manifest",manifest},{"container","mp4"},{"audioOnly",false},{"audioExpected",false},{"height",360},{"tracks",Json::array({{{"kind","video"},{"periodId","p0"},{"adaptationId","v"},{"representationId","r"},{"credentialUrls",Json::array()}}})}};
