 while(manager.isActive(job)&&GetTickCount64()<deadline){{Lock lock(manager.mutex);const auto phase=str(job->data,"MediaPhase");if(phase!=previous){observations.push_back({{"phase",phase},{"size",num(job->data,"Size",-1)},{"capturedSeconds",real(job->data,"LiveCapturedSeconds")}});previous=phase;}if(phase.find("Recording")!=std::string::npos||phase.find("Waiting for live")!=std::string::npos)sawUnknown=sawUnknown||num(job->data,"Size",-1)<0;}Sleep(20);}
